/** Runs every step in order. */
export async function runFlow(page: Page, vars: Vars): Promise<Outputs> {
  const outputs: Outputs = {};
  await page.goto('http://127.0.0.1:8069/');
  await steps['01-signin'](page, { d1: '', d2: '', d3: '', d4: '', d5: '', d6: '', d7: '', d8: '', v2: `${vars.runid} Bench Customer`, v3: 'Benchville' }, outputs);
  await steps['02-create'](page, { d1: '', d2: '', d3: '', v1: `${vars.runid} Bench Customer` }, outputs);
  await steps['03-open'](page, { v1: outputs['02-create.quotation_ref'] ?? '', v2: `${vars.runid} Bench Customer`, v4: outputs['02-create.product_name'] ?? '' }, outputs);
  await steps['04-open'](page, { v1: outputs['02-create.quotation_ref'] ?? '', v2: `${vars.runid} Bench Customer`, v4: outputs['02-create.product_name'] ?? '' }, outputs);
  await steps['05-open'](page, { v1: outputs['02-create.quotation_ref'] ?? '', v2: `${vars.runid} Bench Customer` }, outputs);
  await steps['06-open'](page, { v1: 'S00022', v2: 'fwod34-n2' }, outputs);
  await steps['07-open'](page, { v1: outputs['02-create.quotation_ref'] ?? '', v2: outputs['02-create.url.q.id'] ?? '', v3: 'Sales Order' }, outputs);
  await steps['08-open'](page, { v1: outputs['02-create.quotation_ref'] ?? '', v3: 'Sales Order' }, outputs);
  await steps['09-change'](page, { v1: outputs['02-create.quotation_ref'] ?? '' }, outputs);
  return outputs;
}
